import React from 'react';
import { Box, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
import { ContentfulLivePreview } from '@contentful/live-preview';
import type { ContentfulRichText } from '../../types/contentful';

type DuplexSectionProps = {
  duplexSection: ContentfulRichText;
  entryId?: string;
  locale?: string;
};

const renderRichText = (richText: ContentfulRichText): React.ReactNode => {
  if (!richText.content || richText.content.length === 0) {
    return null;
  }

  return richText.content.map((node, index) => {
    if (node.nodeType === 'text' && node.value) {
      const text = node.value;
      if (node.marks && node.marks.length > 0) {
        const markTypes = node.marks.map((mark) => mark.type);
        if (markTypes.includes('bold')) {
          return <strong key={index}>{text}</strong>;
        }
        if (markTypes.includes('italic')) {
          return <em key={index}>{text}</em>;
        }
      }
      return text;
    }

    if (node.nodeType === 'paragraph' && node.content) {
      return (
        <Text key={index} mb={4}>
          {renderRichText({ nodeType: 'document', data: {}, content: node.content })}
        </Text>
      );
    }

    if (node.nodeType === 'heading-1' && node.content) {
      return (
        <Text as="h1" key={index} fontSize="4xl" fontWeight="bold" mb={4}>
          {renderRichText({ nodeType: 'document', data: {}, content: node.content })}
        </Text>
      );
    }

    if (node.nodeType === 'heading-2' && node.content) {
      return (
        <Text as="h2" key={index} fontSize="3xl" fontWeight="bold" mb={4}>
          {renderRichText({ nodeType: 'document', data: {}, content: node.content })}
        </Text>
      );
    }

    return null;
  });
};

export const DuplexSection = ({ duplexSection, entryId, locale = 'en-US' }: DuplexSectionProps) => {
  const inspectorProps = entryId ? ContentfulLivePreview.getProps({ entryId, fieldId: 'duplexSection', locale }) : {};

  return (
    <Box padding={8} maxWidth="container.xl" marginX="auto" {...inspectorProps}>
      {renderRichText(duplexSection)}
    </Box>
  );
};
